AAC,CAAC,MAAM,EAAE,EAAC,QAAQ,EAAE,QAAQ,IAAI,CAAC,WAAW,IAAI,CAAC,SAAS,EAAC,CAAC;gBACzE,oBAAC,IAAI,IACD,EAAE,EAAE,IAAI,CAAC,KAAK,CAAC,EAAE,EACjB,IAAI,EAAE,IAAI,CAAC,KAAK,CAAC,IAAI,EACrB,gBAAgB,EAAE,CAAC,UAAU,EAC7B,KAAK,EAAE,KAAK,EACZ,MAAM,EAAE,MAAM,EACd,SAAS,EAAE,SAAS,EACpB,aAAa,EAAE,aAAa,EAC5B,kBAAkB,EAAE,IAAI,CAAC,KAAK,CAAC,kBAAkB,EACjD,MAAM,EAAE,IAAI,CAAC,KAAK,CAAC,MAAM,EACzB,kBAAkB,EAAE,IAAI,CAAC,KAAK,CAAC,kBAAkB,EACjD,iBAAiB,EAAE,IAAI,CAAC,KAAK,CAAC,iBAAiB,EAC/C,YAAY,EAAE,IAAI,CAAC,KAAK,CAAC,YAAY,EACrC,UAAU,EAAE,IAAI,CAAC,KAAK,CAAC,UAAU,GACnC,CACA;YACL,CAAC,SAAS,IAAI,IAAI,CAAC,aAAa,EAAE;YAClC,gBAAgB,CACf,CACT,CAAC;IACN,CAAC;;AA3MM,oBAAW,GAAG,cAAc,AAAjB,CAAkB;AA8MxC,MAAM,oBAAoB,GAAG,KAAK,CAAC,UAAU,CACzC,CAAC,KAAK,EAAE,GAAG,EAAE,EAAE;IACX,OAAO,oBAAC,QAAQ,oBAAK,KAAK,IAAE,YAAY,EAAE,GAAG,IAAI,CAAC;AACtD,CAAC,CACJ,CAAC;AAEF,oBAAoB,CAAC,WAAW,GAAG,sBAAsB,CAAC;AAE1D,eAAe,oBAAoB,CAAC","sourcesContent":["import React from 'react';\n\nimport {FOCUSED_CLASS_NAME} from '../../constants';\nimport {DashKitContext} from '../../context';\nimport type {ConfigItem, ConfigLayout} from '../../shared';\nimport type {PluginRef, PluginWidgetProps, ReactGridLayoutProps} from '../../typings';\nimport {cn} from '../../utils/cn';\nimport type {DashKitProps} from '../DashKit';\nimport Item from '../Item/Item';\nimport OverlayControls from '../OverlayControls/OverlayControls';\n\nimport './GridItem.scss';\n\nconst b = cn('dashkit-grid-item');\n\nclass WindowFocusObserver {\n    subscribers = 0;\n    isFocused = !document.hidden;\n\n    constructor() {\n        window.addEventListener('blur', this.blurHandler, true);\n        window.addEventListener('focus', this.focusHandler, true);\n    }\n\n    blurHandler = (e: FocusEvent) => {\n        if (e.target === window) {\n            this.isFocused = false;\n        }\n    };\n\n    focusHandler = (e: FocusEvent) => {\n        if (e.target === window) {\n            this.isFocused = true;\n        }\n    };\n\n    // Method to get state after all blur\\focus events in document are triggered\n    async getFocusedState(): Promise<boolean> {\n        return new Promise((resolve) => {\n            requestAnimationFrame(() => {\n                resolve(this.isFocused);\n            });\n        });\n    }\n}\n\nconst windowFocusObserver = new WindowFocusObserver();\n\ntype DashkitGridDataAttribute =\n    | 'data-dashkit-grid-cols'\n    | 'data-dashkit-grid-h'\n    | 'data-dashkit-grid-margin-x'\n    | 'data-dashkit-grid-margin-y'\n    | 'data-dashkit-grid-padding-x'\n    | 'data-dashkit-grid-padding-y'\n    | 'data-dashkit-grid-row-height'\n    | 'data-dashkit-grid-use-css-transforms'\n    | 'data-dashkit-grid-w'\n    | 'data-dashkit-grid-x'\n    | 'data-dashkit-grid-y';\n\ntype GridItemProps = {\n    adjustWidgetLayout: PluginWidgetProps['adjustWidgetLayout'];\n    gridLayout?: ReactGridLayoutProps;\n    id: string;\n    item: ConfigItem;\n    isDragging?: boolean;\n    isDraggedOut?: boolean;\n    layout: ConfigLayout[];\n\n    forwardedRef?: React.Ref<HTMLDivElement>;\n    forwardedPluginRef?: (pluginRef: PluginRef) => void;\n    isPlaceholder?: boolean;\n\n    onItemMountChange?: DashKitProps['onItemMountChange'];\n    onItemRender?: DashKitProps['onItemRender'];\n\n    // from react-grid-layout:\n    children?: React.ReactNode;\n    className?: string;\n    style?: React.CSSProperties;\n    noOverlay?: boolean;\n    focusable?: boolean;\n    withCustomHandle?: boolean;\n    onMouseDown?: (e: React.MouseEvent<HTMLDivElement>) => void;\n    onMouseUp?: (e: React.MouseEvent<HTMLDivElement>) => void;\n    onTouchEnd?: (e: React.TouchEvent<HTMLDivElement>) => void;\n    onTouchStart?: (e: React.TouchEvent<HTMLDivElement>) => void;\n    onItemFocus?: DashKitProps['onItemFocus'];\n    onItemBlur?: DashKitProps['onItemBlur'];\n} & Partial<Record<DashkitGridDataAttribute, string>>;\n\ntype GridItemState = {\n    isFocused: boolean;\n};\n\nexport class GridItem extends React.PureComponent<GridItemProps, GridItemState> {\n    static contextType = DashKitContext;\n    context!: React.ContextType<typeof DashKitContext>;\n\n    _isAsyncItem = false;\n    _isMounted = false;\n    controller: AbortController | null = null;\n\n    state: GridItemState = {\n        isFocused: false,\n    };\n\n    componentDidMount() {\n        this._isMounted = true;\n    }\n\n    componentWillUnmount() {\n        this._isMounted = false;\n        if (this.controller) {\n            this.controller.abort();\n        }\n    }\n\n    renderOverlay() {\n        const {isPlaceholder} = this.props;\n        const {editMode} = this.context;\n\n        if (editMode && this.props.item.data._editActive) {\n            // needed for correst pointer-events: none work in firefox\n            return <div className={b('overlay-placeholder')} />;\n        }\n\n        if (!editMode || this.props.item.data._editActive || isPlaceholder) {\n            return null;\n        }\n\n        const {item, focusable} = this.props;\n\n        return (\n            <React.Fragment>\n                <div className={b('overlay')} />\n                <OverlayControls\n                    configItem={item}\n                    onItemClick={focusable ? this.onOverlayItemClick : undefined}\n                />\n            </React.Fragment>\n        );\n    }\n\n    onOverlayItemClick = () => {\n        // Creating button element to trigger focus out\n        const focusDummy = document.createElement('button');\n        Object.assign(focusDummy.style, {\n            width: '0',\n            height: '0',\n            opacity: '0',\n            position: 'fixed',\n            top: '0',\n            left: '0',\n        });\n\n        // requestAnimationFrame to make call after alert() or confirm()\n        requestAnimationFrame(() => {\n            if (!this._isMounted) {\n                return;\n            }\n\n            // Adding elment an changing focus\n            document.body.appendChild(focusDummy);\n            focusDummy.focus();\n            document.body.removeChild(focusDummy);\n\n            this.setState({isFocused: false});\n        });\n    };\n\n    onFocusHandler = () => {\n        this.setState({isFocused: true});\n\n        if (this.props.onItemFocus) {\n            // Sync focus and blur handlers\n            windowFocusObserver.getFocusedState().then(() => {\n                this.props.onItemFocus?.(this.props.item);\n            });\n        }\n\n        if (this.controller) {\n            this.controller.abort();\n        }\n    };\n\n    onBlurHandler = () => {\n        this.controller = new AbortController();\n\n        windowFocusObserver.getFocusedState().then((isWindowFocused) => {\n            if (!this.controller?.signal.aborted && isWindowFocused) {\n                this.setState({isFocused: false});\n                this.props.onItemBlur?.(this.props.item);\n            }\n\n            this.controller = null;\n        });\n    };\n\n    render() {\n        // из-за бага, что Grid Items unmounts при изменении static, isDraggable, isResaizable\n        // https://github.com/STRML/react-grid-layout/issues/721\n        const {\n            style,\n            onMouseDown,\n            onMouseUp,\n            onTouchEnd,\n            onTouchStart,\n            children,\n            className,\n            isDragging,\n            isDraggedOut,\n            noOverlay,\n            focusable,\n            withCustomHandle,\n            isPlaceholder = false,\n        } = this.props;\n        const {editMode} = this.context;\n        const {isFocused} = this.state;\n\n        const width =\n            style?.width === undefined ? undefined : Number.parseInt(String(style.width), 10);\n        const height =\n            style?.height === undefined ? undefined : Number.parseInt(String(style.height), 10);\n        const transform = style?.transform;\n        const preparedClassName =\n            (editMode\n                ? className\n                : className\n                      ?.replace('react-resizable', '')\n                      .replace('react-draggable', '')\n                      .replace(FOCUSED_CLASS_NAME, '')) +\n            (isFocused ? ` ${FOCUSED_CLASS_NAME}` : '');\n        const computedClassName = b(\n            {\n                'is-dragging': isDragging,\n                'is-dragged-out': isDraggedOut,\n                'is-focused': isFocused,\n                'with-custom-handle': withCustomHandle,\n            },\n            preparedClassName,\n        );\n\n        const preparedChildren = editMode ? children : null;\n        const reactGridLayoutProps = editMode\n            ? {onMouseDown, onMouseUp, onTouchEnd, onTouchStart}\n            : {};\n        const reactFocusProps = focusable\n            ? {\n                  onFocus: this.onFocusHandler,\n                  onBlur: this.onBlurHandler,\n                  tabIndex: -1,\n              }\n            : {};\n        const {_editActive} = this.props.item.data;\n\n        return (\n            <div\n                className={computedClassName}\n                data-qa=\"dashkit-grid-item\"\n                data-dashkit-grid-cols={this.props['data-dashkit-grid-cols']}\n                data-dashkit-grid-h={this.props['data-dashkit-grid-h']}\n                data-dashkit-grid-margin-x={this.props['data-dashkit-grid-margin-x']}\n                data-dashkit-grid-margin-y={this.props['data-dashkit-grid-margin-y']}\n                data-dashkit-grid-padding-x={this.props['data-dashkit-grid-padding-x']}\n                data-dashkit-grid-padding-y={this.props['data-dashkit-grid-padding-y']}\n                data-dashkit-grid-row-height={this.props['data-dashkit-grid-row-height']}\n                data-dashkit-grid-use-css-transforms={\n                    this.props['data-dashkit-grid-use-css-transforms']\n                }\n                data-dashkit-grid-w={this.props['data-dashkit-grid-w']}\n                data-dashkit-grid-x={this.props['dat