"'`import {
  ActionPanel,
  DashKit,
  DashKitDnDWrapper,
  pluginTitle,
} from '"'@gravity-ui/dashkit';"'`,
`import {
  ActionPanel,
  DashKit,
  DashKitDnDWrapper,
} from '"'@gravity-ui/dashkit';"'`
);
dashboard = dashboard.replace(
`import { ChartColumn, ChartDonut, ListCheck, Text as TextIcon } from '"'@gravity-ui/icons';"'`,
`import { ChartColumn, ChartDonut, ListCheck, Signal, Text as TextIcon } from '"'@gravity-ui/icons';"'`
);
dashboard = dashboard.replace(
`    performance: <ChartDonut width={20} height={20} />,`,
`    performance: <Signal width={20} height={20} />,`
);
fs.writeFileSync(dashboardPath, dashboard);

const cssPath = '"'src/dashboard.css';
let css = fs.readFileSync(cssPath, 'utf8');
css = css.replace(
"'`.widget-shell {
  min-width: 0;
  min-height: 100%;
  overflow: hidden;
}`,
`.widget-shell {
  height: 100%;
  min-width: 0;
  padding: var(--g-spacing-4);
  overflow: hidden;
}`
);
css = css.replace(
`.widget-body {
  width: 100%;
}`,
`.widget-body {
  width: 100%;
  min-height: 0;
}`
);
css += `
.table-cell-main {
  flex: 1;
  min-width: 0;
}

.table-cell-progress {
  flex-shrink: 0;
}
`;
fs.writeFileSync(cssPath, css);
NODE
npm run build'

